begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to app_server;
set local search_path=public,extensions;
select no_plan();
insert into public.businesses(id,slug,name) values('1d000000-0000-4000-8000-000000000001','public-booking','Public booking fixture'),('1d000000-0000-4000-8000-000000000002','public-other','Other fixture');
insert into public.business_settings(business_id,min_notice_minutes,privacy_policy_version) values('1d000000-0000-4000-8000-000000000001',0,'test-notice-v1');
insert into public.staff_members(id,business_id,display_name) values('3d000000-0000-4000-8000-000000000001','1d000000-0000-4000-8000-000000000001','Public staff');
insert into public.services(id,business_id,name,price_cents,duration_minutes,buffer_minutes) values('5d000000-0000-4000-8000-000000000001','1d000000-0000-4000-8000-000000000001','Public service',150000,30,15);
insert into public.staff_services(business_id,staff_member_id,service_id) values('1d000000-0000-4000-8000-000000000001','3d000000-0000-4000-8000-000000000001','5d000000-0000-4000-8000-000000000001');
insert into auth.users(id,email,email_confirmed_at) values('0d000000-0000-4000-8000-000000000001','public-fixture@example.test',now());
insert into public.business_members(business_id,user_id,role) values('1d000000-0000-4000-8000-000000000001','0d000000-0000-4000-8000-000000000001','owner');
insert into public.staff_working_plans(id,business_id,staff_member_id,effective_from,created_by) values('6d000000-0000-4000-8000-000000000001','1d000000-0000-4000-8000-000000000001','3d000000-0000-4000-8000-000000000001',(clock_timestamp() at time zone 'America/Argentina/Buenos_Aires')::date,'0d000000-0000-4000-8000-000000000001');
insert into public.working_hours(business_id,plan_id,position,weekday,start_minute,end_minute) select '1d000000-0000-4000-8000-000000000001','6d000000-0000-4000-8000-000000000001',n,n,540,1080 from generate_series(1,7)n;
select set_config('pb.day',((clock_timestamp() at time zone 'America/Argentina/Buenos_Aires')::date+1)::text,true);
select set_config('pb.envelope',jsonb_build_object('key_id','test','nonce',repeat('c',16),'tag',repeat('d',22),'ciphertext',repeat('e',58))::text,true);
select ok((select count(*)=8 and bool_and(relrowsecurity and relforcerowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='app' and c.relname in ('public_booking_runtime','public_attempts','public_quotes','public_manage_tokens','public_booking_requests','public_rate_buckets','public_challenges','public_privacy_ack')),'eight public-flow tables force RLS');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join unnest(array['anon','authenticated','app_server','service_role']) r where n.nspname='app' and c.relname like 'public_%' and has_table_privilege(r,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')),'no application role has direct private table privileges');
set local role app_server;
select is(app_internal.public_runtime_ready(),false,'default runtime disabled even in a development database');
select throws_ok($$select app_internal.public_issue_attempt('public-booking',gen_random_uuid(),repeat('a',43))$$,'PT503','PUBLIC_BOOKING_DISABLED','fail closed without disposable marker');
reset role;update app.public_booking_runtime set disposable=true;
set local role app_server;
select lives_ok($$select app_internal.public_issue_attempt('public-booking','8d000000-0000-4000-8000-000000000001',repeat('a',43))$$,'issue attempt without Auth account');
select set_config('pb.preview',app_internal.public_availability('public-booking','3d000000-0000-4000-8000-000000000001','5d000000-0000-4000-8000-000000000001',current_setting('pb.day'),1)::text,true);
select is(jsonb_array_length(current_setting('pb.preview')::jsonb->'slots'),35,'working-day slots computed without occupation');
select ok(not (current_setting('pb.preview')::jsonb ?|array['occupied','blocks','staff_version','global_version','business_version','settings_version','customer_id']),'public availability has no occupation or internal versions');
reset role;
create function pg_temp.pbdata(p_time text default '09:00:00',p_name text default 'Public customer') returns jsonb language sql as $$select jsonb_build_object('staff_id','3d000000-0000-4000-8000-000000000001','service_id','5d000000-0000-4000-8000-000000000001','starts_at',current_setting('pb.day')||'T'||p_time||'-03:00','quote_id',current_setting('pb.preview')::jsonb->>'quote_id','customer',jsonb_build_object('full_name',p_name,'phone_raw','1144445555'),'privacy_policy_version','test-notice-v1');$$;
create function pg_temp.pbcreate(p_id uuid default '7d000000-0000-4000-8000-000000000001',p_time text default '09:00:00',p_key uuid default '9d000000-0000-4000-8000-000000000001',p_secret text default repeat('a',43),p_name text default 'Public customer') returns jsonb language sql as $$select app_internal.public_create('public-booking','8d000000-0000-4000-8000-000000000001',p_secret,p_id,p_key,pg_temp.pbdata(p_time,p_name),repeat('b',43),(current_setting('pb.day')||'T'||p_time||'-03:00')::timestamptz+interval '24 hours',current_setting('pb.envelope')::jsonb);$$;
grant execute on function pg_temp.pbdata(text,text),pg_temp.pbcreate(uuid,text,uuid,text,text) to app_server;
set local role app_server;
select is(pg_temp.pbcreate()->>'status','confirmed','public creation confirmed');
select is(pg_temp.pbcreate()->>'version','1','same authority replay returns original version');
select throws_ok($$select pg_temp.pbcreate('7d000000-0000-4000-8000-000000000001','10:00:00')$$,'PT409','IDEMPOTENCY_KEY_REUSED','different intention conflicts inside replay window');
select throws_ok($$select pg_temp.pbcreate('7d000000-0000-4000-8000-000000000001','09:00:00','9d000000-0000-4000-8000-000000000001',repeat('x',43))$$,'PT404','NOT_FOUND','key/UUID do not authorize a replay');
select throws_ok($$select pg_temp.pbcreate(gen_random_uuid(),'09:30:00',gen_random_uuid())$$,'PT409','ATTEMPT_ALREADY_USED','an attempt cannot authorize a second appointment');
select lives_ok($$select app_internal.public_issue_attempt('public-booking','8d000000-0000-4000-8000-000000000002',repeat('z',43))$$,'fresh intention has separate authority');
select throws_ok($$select app_internal.public_create('public-booking','8d000000-0000-4000-8000-000000000002',repeat('z',43),gen_random_uuid(),gen_random_uuid(),pg_temp.pbdata('09:30:00'),repeat('b',43),(current_setting('pb.day')||'T09:30:00-03:00')::timestamptz+interval '24 hours',current_setting('pb.envelope')::jsonb)$$,'PT409','SLOT_TAKEN','another authority cannot overlap the buffer');
select is(app_internal.public_create('public-booking','8d000000-0000-4000-8000-000000000002',repeat('z',43),'7d000000-0000-4000-8000-000000000002',gen_random_uuid(),pg_temp.pbdata('10:00:00'),repeat('t',43),(current_setting('pb.day')||'T10:00:00-03:00')::timestamptz+interval '24 hours',current_setting('pb.envelope')::jsonb)->>'version','1','new intention with shared contact creates another independent customer');
select throws_ok($$select app_internal.public_read('public-booking','7d000000-0000-4000-8000-000000000001',repeat('x',43))$$,'PT404','NOT_FOUND','wrong manage secret denied');
select ok(not (app_internal.public_read('public-booking','7d000000-0000-4000-8000-000000000001',repeat('b',43)) ?|array['customer_id','phone_raw','email','private_notes','events','envelope']),'management detail is a minimal appointment projection');
reset role;
select is((select count(*) from public.customers where business_id='1d000000-0000-4000-8000-000000000001'),2::bigint,'replay and failed overlap did not create extra customers');
select is((select count(distinct customer_id) from public.appointments where business_id='1d000000-0000-4000-8000-000000000001'),2::bigint,'same contact never links customers');
select ok((select bool_and(created_by is null and creator_type='public' and creator_attempt_id is not null) from public.appointments where business_id='1d000000-0000-4000-8000-000000000001'),'no fictitious Auth user for public origin');
select ok((select bool_and(actor_user_id is null and actor_member_id is null and actor_type='public') from public.appointment_events where business_id='1d000000-0000-4000-8000-000000000001'),'real public event actor persisted');
select is((select count(*) from app.public_privacy_ack where business_id='1d000000-0000-4000-8000-000000000001'),2::bigint,'notice version evidence distinct from marketing');
select ok(not exists(select 1 from app.public_booking_requests where result::text like '%114444%' or result::text like '%bbbbbbbb%'),'ledger has no contacts or plaintext token');
select ok(not exists(select 1 from public.audit_logs where business_id='1d000000-0000-4000-8000-000000000001' and (after_data::text like '%114444%' or after_data::text like '%bbbbbbbb%')),'audit has no personal payload or plaintext token');
update public.business_settings set max_client_reschedules=0 where business_id='1d000000-0000-4000-8000-000000000001';
set local role app_server;
select throws_ok($$select app_internal.public_change('public-booking','7d000000-0000-4000-8000-000000000001',repeat('b',43),'reschedule',gen_random_uuid(),1,jsonb_build_object('starts_at',current_setting('pb.day')||'T11:00:00-03:00','quote_id',current_setting('pb.preview')::jsonb->>'quote_id'),(current_setting('pb.day')||'T11:00:00-03:00')::timestamptz+interval '24 hours',current_setting('pb.envelope')::jsonb)$$,'PT409','POLICY_WINDOW_CLOSED','reschedule count ceiling enforced before quote state');
reset role;
update public.business_settings set max_client_reschedules=2,cancellation_cutoff_hours=48 where business_id='1d000000-0000-4000-8000-000000000001';
set local role app_server;
select throws_ok($$select app_internal.public_change('public-booking','7d000000-0000-4000-8000-000000000001',repeat('b',43),'cancel',gen_random_uuid(),1,'{}')$$,'PT409','POLICY_WINDOW_CLOSED','public cancellation cutoff enforced');
reset role;
update public.business_settings set cancellation_cutoff_hours=0 where business_id='1d000000-0000-4000-8000-000000000001';
update app.public_attempts set expires_at=clock_timestamp()-interval '1 second' where id='8d000000-0000-4000-8000-000000000001';
set local role app_server;
select throws_ok($$select pg_temp.pbcreate()$$,'PT404','NOT_FOUND','expired attempt cannot replay');
select is(app_internal.public_read('public-booking','7d000000-0000-4000-8000-000000000001',repeat('b',43))->>'status','confirmed','management has its own TTL independent of creation cookie');
select throws_ok($$select app_internal.public_change('public-booking','7d000000-0000-4000-8000-000000000001',repeat('b',43),'cancel',gen_random_uuid(),null,'{}')$$,'PT428','PRECONDITION_REQUIRED','If-Match required after capability authorization');
select throws_ok($$select app_internal.public_change('public-booking','7d000000-0000-4000-8000-000000000001',repeat('x',43),'cancel',gen_random_uuid(),null,'{}')$$,'PT404','NOT_FOUND','invalid capability cannot probe missing version');
select is(app_internal.public_change('public-booking','7d000000-0000-4000-8000-000000000001',repeat('b',43),'cancel','9d000000-0000-4000-8000-000000000002',1,'{}')->>'status','cancelled','valid future cancellation');
select is(app_internal.public_change('public-booking','7d000000-0000-4000-8000-000000000001',repeat('b',43),'cancel','9d000000-0000-4000-8000-000000000002',1,'{}')->>'version','2','cancel replay has one mutation');
reset role;
select is((select count(*) from app.appointment_occupancy where appointment_id='7d000000-0000-4000-8000-000000000001' and released_at is null),0::bigint,'cancellation releases slot');
update app.public_manage_tokens set expires_at=clock_timestamp()-interval '1 second' where appointment_id='7d000000-0000-4000-8000-000000000001';
set local role app_server;
select throws_ok($$select app_internal.public_read('public-booking','7d000000-0000-4000-8000-000000000001',repeat('b',43))$$,'PT404','NOT_FOUND','expired token denied even for cancelled read');
reset role;
select is(app.rotate_public_capability('1d000000-0000-4000-8000-000000000001','7d000000-0000-4000-8000-000000000002',repeat('r',43),clock_timestamp()+interval '2 days',current_setting('pb.envelope')::jsonb),2,'private maintenance rotation creates another generation');
select ok((select count(*)=1 and bool_and(actor_type='system' and actor_user_id is null and after_data::text not like '%rrrrrrrr%') from public.audit_logs where business_id='1d000000-0000-4000-8000-000000000001' and action='public_token.rotated'),'private rotation records real maintenance metadata without bearer or fictitious user');
set local role app_server;
select throws_ok($$select app_internal.public_read('public-booking','7d000000-0000-4000-8000-000000000002',repeat('t',43))$$,'PT404','NOT_FOUND','rotated generation revoked');
select is(app_internal.public_read('public-booking','7d000000-0000-4000-8000-000000000002',repeat('r',43))->>'generation','2','new generation valid');
select throws_ok($$select app.rotate_public_capability('1d000000-0000-4000-8000-000000000001','7d000000-0000-4000-8000-000000000002',repeat('r',43),clock_timestamp()+interval '2 days',current_setting('pb.envelope')::jsonb)$$,'42501',null,'app_server cannot rotate or recover arbitrary tokens');
select ok(app_internal.public_quota('write','fixture',gen_random_uuid(),clock_timestamp()+interval '1 minute'),'one challenge consumption');
reset role;
set constraints all immediate;
set constraints all deferred;
update app.public_manage_tokens set expires_at=clock_timestamp()-interval '1 second' where appointment_id='7d000000-0000-4000-8000-000000000002' and generation=2;
select set_config('pb.settings_version',(select version::text from public.business_settings where business_id='1d000000-0000-4000-8000-000000000001'),true);
set local role authenticated;set local "request.jwt.claim.sub"='0d000000-0000-4000-8000-000000000001';set local "request.jwt.claims"='{"aal":"aal2"}';
select lives_ok($$select api.manage_appointment('1d000000-0000-4000-8000-000000000001','reschedule','7d000000-0000-4000-8000-000000000002',jsonb_build_object('starts_at',current_setting('pb.day')||'T11:00:00-03:00','context_versions',jsonb_build_object('staff',1,'calendar',1,'settings',current_setting('pb.settings_version')::integer,'business',1)),gen_random_uuid(),1)$$,'admin can move public appointment with the same administrative guards');
reset role;set local role app_server;
select throws_ok($$select app_internal.public_read('public-booking','7d000000-0000-4000-8000-000000000002',repeat('r',43))$$,'PT404','NOT_FOUND','admin move cannot revive expired management capability');
reset role;
set constraints all immediate;
select throws_ok('select app.purge_public_booking(501)','PT400','VALIDATION_ERROR','public private maintenance batch is capped');
update app.public_booking_requests set created_at=clock_timestamp()-interval '49 hours' where business_id='1d000000-0000-4000-8000-000000000001';
update app.public_quotes set expires_at=clock_timestamp()-interval '1 second' where business_id='1d000000-0000-4000-8000-000000000001';
update app.public_challenges set expires_at=clock_timestamp()-interval '1 second';
update app.public_rate_buckets set bucket=clock_timestamp()-interval '3 minutes';
select set_config('pb.purge',app.purge_public_booking(1)::text,true);
select is(current_setting('pb.purge')::jsonb->>'requests','1','purge respects a one-row ledger batch');
select is(current_setting('pb.purge')::jsonb->>'quotes','1','purge removes expired selection quotes');
select is(current_setting('pb.purge')::jsonb->>'challenges','1','purge removes expired test challenges');
select is(current_setting('pb.purge')::jsonb->>'buckets','1','purge removes old quota buckets');
select is((select count(*) from public.appointments where business_id='1d000000-0000-4000-8000-000000000001'),2::bigint,'purge preserves all bookings');
select is((select count(*) from public.appointment_events where business_id='1d000000-0000-4000-8000-000000000001'),4::bigint,'purge preserves all domain events');
select * from finish();rollback;
